const run = $input.first().json;
if (run.status !== 'SUCCEEDED' || run.actId !== 'WecREidW3gHipWFzP') throw new Error('Run incomplete or wrong Actor; inspect this run before retrying');
return [{json:run}];

const metadata = $input.first().json.body?.data;
if (!metadata || !Number.isInteger(metadata.itemCount) || metadata.itemCount > 10000) throw new Error('Dataset requires pagination; use the API recipe instead');
return [{json:metadata}];

const rows = $input.first().json.body;
const count = $('Validate size').first().json.itemCount;
const summary = $('Read summary').first().json.body;
const run = $('Require completed run').first().json;
if (!Array.isArray(rows) || rows.length !== count) throw new Error('Incomplete dataset; no downstream write');
if (!summary || typeof summary !== 'object' || Array.isArray(summary)) throw new Error('Missing RUN_SUMMARY');
// NOT_FOUND is a verified empty answer. PARTIAL and FAILED are unfinished checks, never "no data".
const changeTypes = ['BREAKOUT_NEW', 'RISING_QUERY_NEW', 'RISING_QUERY_CHANGED', 'TRENDING_TOPIC_NEW'];
const ok = r => r.status === 'SUCCESS' && r.record_type !== 'group_status';
const events = rows.filter(r => ok(r) && changeTypes.includes(r.change_type));
const baseline = rows.filter(r => ok(r) && r.change_type === 'BASELINE');
const groupStatus = rows.filter(r => r.record_type === 'group_status');
const problems = rows.filter(r => r.status === 'PARTIAL' || r.status === 'FAILED');
return [{json: {runId: run.id, summary, events, baseline, groupStatus, problems, rows}}];
